	.md-render .rapier-code-lines-note{display:none!important}
}

.md-render .table-scroll-wrap{width:100%;margin:0 0 var(--md-gap-block);overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:2px}
.md-render .table-scroll-wrap table{min-width:100%;margin-bottom:0}
@media screen{
	.md-render{--md-table-header-top:0px}
	.md-render .table-scroll-wrap{overflow:auto clip}
	.md-render thead{position:sticky;top:var(--md-table-header-top,0px);z-index:2;background:var(--md-color-bg)}
}
@media print{
  .md-render [data-md-break]{border:0!important;height:0!important;margin:0!important;break-before:page;page-break-before:always}
  .md-render [data-md-break]::after{content:none!important}
}

