  const slice = (start, end) => {
    const selected = [];
    let at = 0;
    for (const piece of pieces) {
      const low = Math.max(start, at), high = Math.min(end, at + piece.length);
      if (high > low) selected.push(piece.text === undefined
        ? {from: piece.from + low - at, length: high - low}
