		while (j < line.length && col < 3) {
			const code = line.charCodeAt(j);
			if (code === 32) { col++; j++; }
			else if (code === 9) {
				const adv = 4 - (col % 4);
				if (col + adv > 3) break;
				col += adv; j++;
			} else break;
		}
		if (line.charCodeAt(j) !== 62) break;
		depth++;
		j++;
		if (line.charCodeAt(j) === 32 || line.charCodeAt(j) === 9) j++;
